  VALUES 
    (523::BIGINT, 'Buen profe, bastantes quices, él requiere que usted sea bastante formal a la hora de responder en evaluaciones.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '0fa82ca6635faf7a1c23e8bb6a53f7a4a9bbd243eef40ee75dd5a49535a6690f'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Buen profe. Clases demostrativas. Bastantes quices pero accesibles. Hace gaaps con los que se pueden recuperar puntos.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-25T00:00:00+00:00'::TIMESTAMPTZ, '28131929eb6e5db027bc149076d45292a223693e6a679d53796fc6613086f02d'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Es curioso ver cómo parece ser un gran profesor en clases de mate avanzadas. Pero lo que fue admin no fue tan eficiente; ponía pocos ejemplos y explicaba a la carrera y no calificaba justamente. Además nos dejaba salir una hora antes.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, '15d816098f1c2beb6ba995ef9fe628a18693943722da674ab0a8cac8b73a1375'::TEXT, ARRAY[2439]::BIGINT[]),
    (523::BIGINT, 'Excelente profesor'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Brinda apoyo']::TEXT[], '2025-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'f2d3f16c30cdde7111133863556c93a872cc0bd8c9fbdf0bb3387465c40c205b'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Si tiene la oportunidad de matricular con él, APROVECHELA. Dios santo, nunca en la vida alguien se había preocupado por mi, es EXCELENTE profe y ser humano'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-10-07T00:00:00+00:00'::TIMESTAMPTZ, '62ee17a86f2a1ee6cb3b2afdfd798103582f6b9e07dac3c0fe1913aba080696a'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Excelente profesor, muy ordenado con la materia, deja todo muy claro y siempre dispuesto a abarcar dudas y que todos entiendan. Da ejemplos variados en clase lo que ayuda mucho en los exámenes, sus quizes ayudan mucho para estudiar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'a179f99efea665a15df20b198e1a0c28568e9adce4050ffc53770101e155128b'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Uno de los mejores profes que he tenido en mi carrera. Da un montón de material de apoyo y explica muy bien, sus clases son muy completas y no deja nada por sentado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, '118181994e898847c6952bc142265cb8b6ad676b5dd92af43329a0a9bd032154'::TEXT, ARRAY[923, 634, 605]::BIGINT[]),
    (523::BIGINT, 'Explica muy bien y de verdad le interesa que sus estudiantes entiendan y pasen, hace todo lo posible por ayudar, hace pocos quices y algunos en parejas. Es muy linda persona'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, '3ab0bb595baa023ad18b16dacea19679f481b3b162019116e45f3ca7c413203a'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Exelente profesor, ayuda demasiado fuera de clase, siempre atento a las preguntas y sus respuestas son claras, recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2024-10-22T00:00:00+00:00'::TIMESTAMPTZ, '6ac6c04171ef7fb9488ef949d47e328b3b99dccb91d74cd80f6ff8ddd09f2eab'::TEXT, ARRAY[2439, 1018, 563]::BIGINT[]),
    (523::BIGINT, 'Siempre llega bien guapo a clases'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2024-05-03T00:00:00+00:00'::TIMESTAMPTZ, 'b28e03f28145f37acd31e430997bf8ba4cbe8d6003dde986f3bb9d3f4c9c9ae4'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'es buen profe, explica las veces que sea necesario, además es como un profe de cole, escribe da chance para copiar y luego explica todo de nuevo, hace ejemplos, explica procedimientos y retoma como notas temas de cursos pasados si no están tan frescos, 20/10'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-20T00:00:00+00:00'::TIMESTAMPTZ, '795198f42ac28b35da141e71ad99a8bbc48f44e76e29326584dcc299ff322dc6'::TEXT, ARRAY[605]::BIGINT[]),
    (523::BIGINT, 'Pablo es como mi papá pero si está cuando lo ocupo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'c4ce853d3013f990441f15f3f9db33322fea737d96c7b8004e7f98ece6e4faaa'::TEXT, ARRAY[1018]::BIGINT[]),
    (523::BIGINT, 'Increíble profesor la manera de explicar, la forma en la que trata al estudiante impecable le agarre un cariño a la materia gracias a él y pienso seguir estudiándola a pesar de ser un curso no relacionado con la carrera'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'af5ed507093146fa27633603bdcd70391987264cb15df30b2a89eb045a38471f'::TEXT, ARRAY[1018]::BIGINT[]),
    (523::BIGINT, 'El mejor profe de mate que he tenido, se le entiende todo y se nota que ama enseñar. Se preocupa mucho por el bienestar del estudiante.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'b528efaced999b9db4cc5f2ffcac6f740d73556b6c422765894386bac2b3cbf3'::TEXT, ARRAY[1018]::BIGINT[]),
    (523::BIGINT, 'Buenísimo como docente. Siempre, siempre brinda apoyo, y si tiene que explicar 10 veces lo hace. Siempre mantiene la calma y es demasiado bueno. Las clases son muy largas y monótonas, por lo que puede ser dificil no aburrirse, pero aparte a eso, recomendadísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '1ac02f6172bfc21a5a96d96fa379ebd598b16da4e3e807fb133ac41f247ae003'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Clases muy largas pero probablemente el mejor profesor de matemáticas que he tenido, explica muy bien y deja muchos ejemplos, lo cual es bueno para estudiar pero para una clase virtual se hace muy cansado, por lo que es facil perder el hilo. Siempre se preocupa por que la materia quede clara.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '8517de8cf4efd7b9651af759ec3e13ae2e9f36c5455c95c88a67e0900e8e8a25'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'El profe es un excelente profesor, aclara dudas y saca tiempo antes de cada examen para que podamos repasar. El único detalle es que al final del curso explicaba un poco rápido y eso llegaba a confundir y perderse.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'c3127665c6cc37d034a183be5db50d2bf62c34264d30b72953e4f4d88e35ecf3'::TEXT, ARRAY[2444]::BIGINT[]),
    (523::BIGINT, 'Es muy buen profe la verdad retroalimenta mucho y si usted no entiende o le está costando algo él es muy comprensible y le ayuda, solamente que para mi habla muy despacio y muy tranquilo, a veces le dan ganas de dormir a uno pero en general es buen profe.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2022-01-26T00:00:00+00:00'::TIMESTAMPTZ, '763b59dd815f5fea1f3c2351de9209e6da5b4d65470f9c22189cd312deb5ec9f'::TEXT, ARRAY[1620, 1621]::BIGINT[]),
    (523::BIGINT, 'Excelente profesor, lo que explica viene el examen, los quizes no son duros, explica en word y eso lo sube porlo que no tienes que hacer apuntes, lo unico malo es que las clases son muy largas, pero despues de ahi todo bien, lo recomiendo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '46aac1bb71f723ad6cc68e601e17956594ce1605951df7322670c1b5ece55f5a'::TEXT, ARRAY[923, 634, 605]::BIGINT[]),
    (523::BIGINT, 'Muy buen profe solo que las clases son muy largas y un poco cansado. Pero el explica bastante bien y con bastante práctica se pasa el curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'ed07661e85906913940e60c419d5e6d4900bb9810657051688c755fa63b4563c'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Las clases se pueden sentir muy aburridas. Todo lo que hace lo explica por medio de Word y de nuevo, se hace algo aburrido y no da tiempo a tomar apuntes. Califica suave, se puede pasar fácil porque si explica cosas importantes para el examen.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'f7f3aa4e88dc0a8384c17346bad018280d0c11fc2c6384fd631a40c0844de38e'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'La clase es CERO DINÁMICA parece que da la clase con pereza, explica desde una hoja en Word con las ecuaciones ahí, o sea es un enredo. Me hubiera gustado ver un comentario como este antes de meter con él, porque los que aparecen acá seguro los hace él mismo…'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, '6a31cd3eb0bfe60d251c22f632e5bc268cb4885bdf59050cdc92fe81127a4888'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Virtual explica muy bien, aunque suele ser un poco aburrido. No deja muchas tareas y sus exámenes son duros.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, 'df62dc9acfffd12c58952a5c4b30e649eba2650a1cf67daff0bc79ae46e1170d'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Excelente profesor. Posee mucha organización, claridad y elocuencia a la hora de explicar. Siempre está dispuesto a brindar apoyo y hace que las clases no sean tan pesadas en la modalidad virtual.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'e997fc92d72cab39bc63923b2e834cb202f1f1407702a3a7f2965338132eb04d'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Explica super bien'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '3353b8c173052beda567f35066bc8f13a8aea169f09de47ca890a82d407bba70'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Explica muy bien, solo que las clases son aburridas'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '83234904e171f4283d002b0862b2b0dc5558f8bc5277e118deefd76792dc7764'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Es muy bueno explicando y siempre está en la hora de consulta para ayudar. Siempre explica usando ejemplos que son más difíciles que los del examen y eso hace que uno llegue bien preparado. Lo único negativo es que la clase se hace un poco aburrida en la modalidad virtual pero él está libre de culpa'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '65d71e44d0b26739ce0f47e942caf921190278ab6d2516c7ae46619e0759b033'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Explica la materia muy claro, y deja muchas ejercicios para hacer practica. Siempre ayuda cuando se le pide y esta atento a responder preguntas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '5b552ce0e22a31cfd9b6a4bcb6cdaf8145643860335dd7f70b6b6f43af3c39de'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'El mejor profe de mate que he tenido, por lo general las clases era primero copiar la teoría, luego él la explicaba, hacia ejemplos y también nos ponía ejercicios para que los realizáramos en clases, ayuda bastante con las dudas y en consulta es muy bueno, trata a los estudiantes de forma excelente'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-14T00:00:00+00:00'::TIMESTAMPTZ, '921a0e2a8903cbad46f0f18e6b2bedb635bbe33cca2b47e19fe88b608a7f548f'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Excelente Profe! Clases bien organizadas, con muchos ejemplos que explica con claridad y siempre está buscando la forma de que uno entienda bien la materia. Suele dejar tareas y hace quices constantemente con el fin de que uno repase para el examen y no dejar todo para lo ultimo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'd00844fe0b342a0b9220978259d36f4a84e2408df1a7e890fb52ceb89dadbcb7'::TEXT, ARRAY[605]::BIGINT[]),
    (523::BIGINT, 'Es un excelente profesor, escribe todo en la pizarra y despues explica el tema. Hace algunos ejemplos que dejan clara la materia. Deja muchas tareas que lo preparan al examen y lo mantienen estudiando aunque sea un poco. Eso hace que el curso se vuelva más fácil'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '748c409778093b6689a3c6211754d92cac9f59ebd9422dc608fe82afaef300a8'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Muy buen profe con un estilo muy claro, el teórico. En el caso de las mates, ese estilo no es para todos y fue lo que me sucedió. Si necesita practicar constantemente para salir bien, este no es su profesor. Ojo, esto no quiere decir que sea un mal profe, es excelente, pero no para todos.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'dcc96796afc7a5b8a6d0d762548b414b2810c0d00954dcf32d67446cb54d511f'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Dependiendo de cómo aprende usted, este profe le puede servir o no. Todo lo escribe en la pizarra, es super teórico, pero si usted aprende a punta de pura práctica, no le funciona. Deja tareas demasiado difíciles que consumen bastante tiempo'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'ce3018f98436049fde9f7f0414de7e7a20669f9d44792adde4d01693bb1b41b2'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'afc7ec494e67f5d824a4ba3421e712f671d6dd2d9322900e82b659243ad88af3'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'De los mejores profesores que hay en el TEC'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'c5fd2e055c0bfb6b878a7d92e505c0a45bc7ca8639f556d597ad79c68159740f'::TEXT, ARRAY[605]::BIGINT[]),
    (523::BIGINT, 'Realiza tareas y cuiz cada semana, explica claro y aun mejor si va consulta con el profe'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'db90a28494218a06e2ee6e420a740fb4b9927d9ab76aad61bfcc9d460f959b87'::TEXT, ARRAY[605]::BIGINT[]),
    (523::BIGINT, 'Un profe demasiado bueno y una excelente persona. Explica muy bien (va un toque rápido pero uno le agarra el ritmo), ayuda mucho a los estudiantes y si a uno no le sirve la hora de consulta, él lo atiende en otro momento. SÚPER RECOMENDADO :)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-12T00:00:00+00:00'::TIMESTAMPTZ, '9b82095f63f3af7232c4a818e4ac019a1ca50cd3ce00024d6889f533078b4db3'::TEXT, ARRAY[605]::BIGINT[]),
    (523::BIGINT, 'Hace quices y tareas semanales, las clases son aburridas y se hacen eternas pero el profe es muy bueno.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos exámenes']::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '3c779cdcd143f1562105b5d4b0059fd46c4cde0b387f90722cd314abcf94ad2b'::TEXT, ARRAY[605]::BIGINT[]),
    (523::BIGINT, 'Excelente profe, explica demasiado bien y siempre esta atento a que todos entiendan, ir a consulta con él es lo mejor'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-08-12T00:00:00+00:00'::TIMESTAMPTZ, '949124f09958dc9f22b1d1b3265e0da76ca6ac0ad84f3769627aca54d91f74a5'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Un excelente profesor, se preocupa por que al estudiante todo le quede claro. Gran apoyo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-07-31T00:00:00+00:00'::TIMESTAMPTZ, '8491f3cb47a839b899193fd67a9079a48130e2219c00e479de555b0e9d146368'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Un profe genial, sin embargo es algo lento a la hora de dar la clase y muy monótono'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a4df89dd8e821f1613a065f28ba51da8dbfcfd61184842038220d76d7b8a9b07'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Un muy buen profe de mate, explica las cosas de una forma muy técnica pero de manera simple para que tu las entiendes, no le importa devolverse o explicar las veces que sean necesarias, es muy atento, muy amable y brinda mucho apoyo. Además califica suave y perdona mucho xD'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '9dd03dace33434d5b48055f1b8f6d4f5ed074f50a8732c018d93705083f5bdca'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'A veces se pierde un poco en la explicación pero en general explica muy bien, ayuda mucho si uno le pide ayuda, es excelente ir a consulta con él. Deja tareas en lugar de hacer quizes entonces eso ayuda mucho al final para la nota'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '5d742e83106a8ad53982170785218fb7098a521d681a820895f89139629b9667'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Excelente profesor. Explica muy claro, si no entiende algo, le explicara las veces que sean necesarias. Realiza un quiz o tarea por semana, pero ayudan a practicar. Realiza ejemplos variados sobre un tema, lo que llega a ser de utilidad en los exámenes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '0f62762e819fc9cfe6b2dae4e18b200e12d989bc4fcc39db0fcbfe622c8ade63'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, '6a47deb7dea8064664817a16de09b4bb7464d40c97206973476faa377ad3d006'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-05-25T00:00:00+00:00'::TIMESTAMPTZ, 'b1ceacefd71b3feb779cd12f26071016d4599320323fcb39d6244d47ed16e49b'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'Muy buen profe, explica mil y un veces si así se requiere. Hace quices todas las semanas pero eso ayuda a mantener la materia fresca y no son difíciles, lo mismo con las tareas. Tiene una personalidad tímida aunque dulce. Completamente recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'ccec4a5d42d0eb395b9b9437ffc3a01999ff344c0be13d6e87ae87ae8d8a2b1b'::TEXT, ARRAY[563]::BIGINT[]),
    (523::BIGINT, 'De los mejores profes que he tenido en el TEC, explica cuantas veces sea necesario y de la manera que necesite, siempre hace ejemplos muy buenos y no califica tan duro, es muy ordenado con todo, super recomendado!!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'ca2fc214c6882466cc051c970c330ac0fbd273ce10e27b5f77890cd28cfc668b'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Muy buena gente, explica muy claro con muchos ejemplos. No califica tan rudo como la gente dice, los quizes y tareas al final los pone con 100 si uno entregó todos. Ayuda mucho si uno pide que clarifique algo. 100% recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-09-13T00:00:00+00:00'::TIMESTAMPTZ, '63692d0236eebb9a7f36227df6c54f71b480de3affa8d8c01ae5878c5cfc7869'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '7b6d782220ae214578266e777dd339d850e8eff398b5e910897f5967cf6a96ec'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '6d6c08a226e0d0be12d307b00492385e02d7ea3ca99f8ae34c7f8017f26d8dd1'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Excelente profesor, tiene mucha paciencia y aclara todas las dudas. Hace muchos quices y son díficiles pero de esa forma asegura que la materia se lleve al día. Muestra mucho interés en el aprendizaje del estudiante, súper recomendado!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-21T00:00:00+00:00'::TIMESTAMPTZ, 'c47db53492a0f26f2b604bb7e2c63d2bdc3358074415a3835b4716d564c03643'::TEXT, ARRAY[1018]::BIGINT[]),
    (523::BIGINT, 'De esos pocos profes que son excelentes personas y explican demasiado bien! Las clases son interesantes y uno en serio aprende. Sí califica duro, así que ponga atención en lo que dice en clases. Lo recomiendo al 100%.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'bdbeb02f6d60ef42639f737e32a758db34f515925711fd45c0b4a2ef19beb8e9'::TEXT, ARRAY[1653, 634]::BIGINT[]),
    (523::BIGINT, 'Sin duda el mejor profesor que he tenido respecto a las mates, es muy bueno y lo prepara muy bien para el examen ¿, hace muchas tareas y quices pero es para estar siempre con la materia presente, en consulta es un amor y ayuda muchisimo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '5c6460ea47658b3198aa8898aec9873b5bee828e2dbac63d16d1e5c0024cc4ca'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Excelente, lo motiva a ir a clases, y da consejos utiles. Quices accesibles, lo prepara para el examen y en consulta explica lo q sea necesario para entender, Califica un toque rudillo pero lo recomiendo mucho'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2016-06-20T00:00:00+00:00'::TIMESTAMPTZ, '6b60140d49c1ee458c089b11ea90312f8c715e0095d4d590962cf26628c2a8c5'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Excelente Profesor, muy interesado en el aprendizaje de los estudiantes. Hace suficientes quices para prepararlo a uno para el examen. Lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'b31146450ae828707927f2ec85b7db0f759dbea8cbe1fdef64610a7cfbfe3c81'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Profesor humilde, motiva ir a sus clases, motiva estudiar con él, da la materia super clara con una gran cantidad de ejemplos. Los quices no son tan duros como la gente dice nada más hay que repasar y eso si lo preparan a uno para el examen. No se va a arrepentir de matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, '97eb4b0e52135180bd1a080c341c7a12b6093ed9837a14d997ca0a76e2050708'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'El mejor!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-05T00:00:00+00:00'::TIMESTAMPTZ, '79250e5711f30006150dd46de7bf431099461712c1664ee35f6ce92cde6f714f'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Excelente. Explica demasiado bien'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-04T00:00:00+00:00'::TIMESTAMPTZ, '984ed53f4cd789b9e93c03c628c4187aae005295eb266aa3bcf269e5a7afbd2e'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Excelente profesor, muy amable y da la materia con mucha claridad. Super recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, '6afae203447fc1f9ded24557ffa28a0bc1713d39b35d8e15fc0ab0d83bfd0898'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '838b1bac896a64acfaad3d65806e21a2eacf4b03bb38e0c16375581d31c23ac9'::TEXT, ARRAY[634]::BIGINT[]),
    (523::BIGINT, 'Muy buen profe, explica muy claro, califica según el proseso y no quita puntos por pequeñeces. Los quices son duros, pero lo preparan bien para el examen'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '8b8e128a64ce7addf58e87802d1ce1ea237e60b7c9668aca15b4a5c4b146f519'::TEXT, ARRAY[2920]::BIGINT[]),
    (523::BIGINT, 'Es un profesor excelente. El podría explicar mil veces hasta que un alumno entienda. Ayuda muchísimo ir a las consultas y siempre esta dispuesto a ayudar. A mi parecer no califica duro los exámenes pero tampoco regala los puntos a quien sea. Tiene que ver que tiene interés y si ayuda! Recomendado!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '9c517d9659998da3826cda37cee0b4ba5411a122b84b02f55c20168678242da7'::TEXT, ARRAY[2920]::BIGINT[]),
    (523::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'af848b90f80c94022cb00a57b55d62e5b42bf23046a2de4981d4c84969dd6c96'::TEXT, ARRAY[2920]::BIGINT[]),
    (523::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-09T00:00:00+00:00'::TIMESTAMPTZ, '8c9c6e764033470fe79582b8be42bcfc56e29e646a97a744319d530defcb3f6b'::TEXT, ARRAY[923, 634, 605]::BIGINT[]),
    (523::BIGINT, 'El profe es muy pura vida con la gente, especialmente cundo uno va a consulta. El esta en consulta hasta que uno entienda. Los quices son difíciles pero es para ir preparado para el examen.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '8a7dd0155dc5af1918a90dc70865a7e2dd83b50e3e41316297fe345800b3d880'::TEXT, ARRAY[2920]::BIGINT[]),
    (523::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'f69c220866303e53d506481b2d49e06fda965047c6db4e4aff65b6bcdbc62797'::TEXT, ARRAY[1018]::BIGINT[])
